<?php use SwimlogStandalone\Settings as S;use SwimLogEvaluation\Garmin_Personal_API as API;use SwimLogEvaluation\Garmin_Measurement_Sync as Sync;
$labels=array('swimmer'=>'Swimmer Configuration','locations'=>'Locations','garmin_setup'=>'Garmin Setup');$settingId='new'; ?>
<section class="calendar-panel workout-page" aria-labelledby="settings-title"><div class="workout-page-heading"><h2 id="settings-title"><?php echo esc_html($labels[$screen]); ?></h2></div>
<?php if($configurationError): ?><p role="alert"><?php echo esc_html($configurationError->get_error_message()); ?></p><?php endif;if(isset($_GET['settings_saved'])): ?><p class="save-notice" role="status">Settings saved.</p><?php endif; ?>
<?php if($screen==='swimmer'): $v=S::preferences($owner);$operation='swimmer_save';require __DIR__.'/settings-form-start.php'; ?>
<div class="plan-field"><label for="swimmer-birthdate">Date of birth (private)</label><input id="swimmer-birthdate" type="date" name="birthdate" max="<?php echo esc_attr(wp_date('Y-m-d')); ?>" value="<?php echo esc_attr($v['birthdate']); ?>"></div>
<div class="plan-field"><label for="swimmer-week">First day of calendar week</label><select id="swimmer-week" name="calendar_first_day"><?php foreach(array('saturday'=>'Saturday','sunday'=>'Sunday','monday'=>'Monday')as$key=>$label): ?><option value="<?php echo esc_attr($key); ?>" <?php selected($v['calendar_first_day'],$key); ?>><?php echo esc_html($label); ?></option><?php endforeach; ?></select></div>
<div class="plan-field"><label for="swimmer-volume">Training volume period (months)</label><input id="swimmer-volume" name="training_volume_months" type="number" min="1" max="24" required value="<?php echo esc_attr($v['training_volume_months']); ?>"></div>
<fieldset><legend>Privacy</legend><?php foreach(array('public_results'=>'Allow public swim results','public_ows_routes'=>'Allow public open-water route shapes','rest_api_access'=>'Allow authenticated read-only Swim Log REST API access')as$key=>$label): ?><label class="setting-check"><input type="checkbox" name="<?php echo esc_attr($key); ?>" value="1" <?php checked($v[$key],'1'); ?>><?php echo esc_html($label); ?></label><?php endforeach; ?><p>Public routes can reveal swimming locations. These choices do not make measurements or running/walking activities public.</p></fieldset><button>Save swimmer configuration</button></form>
<?php elseif($screen==='locations'): ?>
<div class="event-list"><?php foreach(\SwimLogEvaluation\Location::all_for_user($owner)as$row): ?><article class="event-list-card"><a href="<?php echo esc_url('/?screen=locations&edit_location='.(int)$row->id); ?>"><?php echo esc_html($row->name); ?></a><p><?php echo esc_html($row->pool_length===null?'Open-water / no pool length':$row->pool_length.' '.$row->pool_unit); ?></p></article><?php endforeach; ?></div>
<p><a class="control" href="/?screen=locations">Add location</a></p><h3><?php echo $configurationLocation?'Edit location':'Add location'; ?></h3>
<?php $settingId=$configurationLocationId;$operation='location_save';require __DIR__.'/settings-form-start.php'; ?><input type="hidden" name="location_id" value="<?php echo esc_attr($settingId); ?>">
<?php foreach(array('name'=>'Location name','pool_length'=>'Pool length (optional)','latitude'=>'Latitude (optional, private)','longitude'=>'Longitude (optional, private)','notes'=>'Location notes (private)')as$key=>$label): ?><div class="plan-field"><label for="location-<?php echo esc_attr($key); ?>"><?php echo esc_html($label); ?></label><?php if($key==='notes'): ?><textarea id="location-notes" name="notes" rows="4" maxlength="12000"><?php echo esc_textarea($configurationLocation->notes??''); ?></textarea><?php else: ?><input id="location-<?php echo esc_attr($key); ?>" name="<?php echo esc_attr($key); ?>" value="<?php echo esc_attr($configurationLocation->$key??''); ?>" <?php if($key==='name')echo 'required maxlength="191"';else echo 'type="number" step="any"'; ?>><?php endif; ?></div><?php endforeach; ?>
<div class="plan-field"><label for="location-unit">Pool unit</label><select id="location-unit" name="pool_unit"><?php foreach(array(''=>'No pool course','m'=>'Meters','yd'=>'Yards')as$key=>$label): ?><option value="<?php echo esc_attr($key); ?>" <?php selected($configurationLocation->pool_unit??'',$key); ?>><?php echo esc_html($label); ?></option><?php endforeach; ?></select></div><button>Save location</button></form>
<?php if($configurationLocation):$operation='location_delete';require __DIR__.'/settings-form-start.php'; ?><input type="hidden" name="location_id" value="<?php echo esc_attr($settingId); ?>"><label class="setting-check"><input type="checkbox" name="confirm_delete" value="1" required>Confirm deletion of this location</label><p>Recorded pool snapshots remain intact; existing references may display an unavailable location.</p><button>Delete location</button></form><?php endif; ?>
<?php else:$verified=S::verified($owner);$settingId='new'; ?>
<p role="status">Connection: <?php echo $verified?'Verified':(API::is_configured($owner)?'Saved — verification required':'Not configured'); ?></p>
<?php $operation='key_save';require __DIR__.'/settings-form-start.php'; ?><div class="plan-field"><label for="garmin-key">Garmin Personal API key</label><input id="garmin-key" name="api_key" type="password" autocomplete="new-password" required value=""><small>The saved key is never displayed. Replacing it requires verification again.</small></div><button>Save API key</button></form>
<?php $operation='key_test';require __DIR__.'/settings-form-start.php'; ?><button>Verify connection</button></form>
<?php if(API::is_configured($owner)):$operation='key_remove';require __DIR__.'/settings-form-start.php'; ?><label class="setting-check"><input type="checkbox" name="confirm_remove" value="1" required>Confirm removal of the saved API key</label><button>Remove API key</button></form><?php endif; ?>
<h3>Automatic synchronization</h3><p>Activity and measurement schedules use the existing WordPress cron jobs. Configuration persists across the WordPress and standalone interfaces. Existing imports and historical jobs are retained if the connection needs repair.</p>
<?php if($verified):$operation='activity_sync';require __DIR__.'/settings-form-start.php';$types=API::scheduled_types($owner); ?>
<label class="setting-check"><input type="checkbox" name="enabled" value="1" <?php checked(get_user_meta($owner,'swimlog_garmin_sync_enabled',true),'1'); ?>>Enable hourly activity synchronization</label><fieldset><legend>Activity types</legend><?php foreach(S::activities($owner)as$key=>$label): ?><label class="setting-check"><input type="checkbox" name="types[]" value="<?php echo esc_attr($key); ?>" <?php checked(in_array($key,$types,true)); ?>><?php echo esc_html($label); ?></label><?php endforeach; ?></fieldset><p>Checks look back seven days. Unmatched open-water locations and ambiguous matches remain for review.</p><button>Save activity synchronization</button></form>
<?php if(current_user_can('swimlog_manage_own_workouts')):$operation='measurement_sync';require __DIR__.'/settings-form-start.php';$categories=Sync::categories($owner); ?><fieldset><legend>Automatic private measurements</legend><?php foreach(S::measurements()as$key=>$label): ?><label class="setting-check"><input type="checkbox" name="categories[]" value="<?php echo esc_attr($key); ?>" <?php checked(in_array($key,$categories,true)); ?>><?php echo esc_html($label); ?></label><?php endforeach; ?></fieldset><p>Clear all categories to stop future automatic measurement imports. Existing measurements remain private and are retained.</p><button>Save measurement synchronization</button></form>
<?php endif;foreach(array('Activity sync'=>'swimlog_garmin_scheduled_sync','Measurement sync'=>Sync::HOOK)as$label=>$hook):$next=wp_next_scheduled($hook,array($owner)); ?><p><?php echo esc_html($label.': '.($next?'next task '.wp_date('Y-m-d H:i',$next,wp_timezone()):'no task scheduled')); ?></p><?php endforeach; ?>
<h3>Synchronization status</h3>
<?php foreach(array('Last activity attempt'=>'swimlog_garmin_sync_last_attempt','Last successful activity sync'=>'swimlog_garmin_sync_last_success')as$label=>$key):$stamp=get_user_meta($owner,$key,true); ?><p><?php echo esc_html($label.': '.(is_string($stamp)&&$stamp!==''?$stamp:'Not recorded')); ?></p><?php endforeach;
$syncError=get_user_meta($owner,'swimlog_garmin_sync_last_error',true);if(is_array($syncError)&&$syncError): ?><p role="alert">The last activity synchronization failed. Verify the connection and review pending imports before retrying.</p><?php endif;
$measurementState=get_user_meta($owner,Sync::STATE,true);if(current_user_can('swimlog_manage_own_workouts')&&is_array($measurementState)): ?><p><?php echo esc_html('Measurement synchronization: '.sanitize_key($measurementState['status']??'unknown').'; last attempt (UTC): '.sanitize_text_field($measurementState['attempt_utc']??'Not recorded')); ?></p><?php endif; ?>
<?php else: ?><p>Verify the connection to configure automatic synchronization.</p><?php endif;endif; ?></section>
